    private static boolean[][] nimTable(int bound) {
        boolean[][] win=new boolean[bound+1][bound+1];
        for(int a=0;a<=bound;a++)for(int b=0;b<=bound;b++) {
            for(int x=0;x<a;x++) if(!win[x][b])win[a][b]=true;
            for(int y=0;y<b;y++) if(!win[a][y])win[a][b]=true;
        }
        return win;
    }
